using System;
using System.IO;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using HarborValeGreybox.Driving;
using HarborValeGreybox.Garage;
using HarborValeGreybox.Racing;
namespace HarborValeGreybox.Boost.Editor {
public static class BoostVerification {
 static List<string> report=new List<string>();static string root;static SimulationMode oldMode;
 static void Check(bool ok,string text){report.Add((ok?"PASS ":"FAIL ")+text);if(!ok)throw new Exception(text);}
 static string Id()=>Guid.NewGuid().ToString("N");
 static TrialSession Finish(TrialDefinition d){var s=new TrialSession(d);s.Tick(4,Vector3.zero,Vector3.zero);s.Tick(90,Vector3.zero,Vector3.zero);foreach(var g in d.checkpoints)s.Tick(.02f,g.Position-g.Forward,g.Position+g.Forward);return s;}
 static bool Denied(Action action){try{action();return false;}catch(InvalidOperationException){return true;}}
 static float LastRollOn;
 static float Acceleration(FinchDefinition d){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/HarborValeGreybox/Expansion/Prefabs/AsterFinch.prefab");var model=(GameObject)PrefabUtility.InstantiatePrefab(prefab);model.transform.position=new Vector3(0,.35f,0);var car=model.AddComponent<FinchVehicle>();car.Initialize();car.externalInput=true;car.InstallPowertrain(d);Physics.SyncTransforms();for(int i=0;i<150;i++){car.Tick(.02f);Physics.Simulate(.02f);}car.commandedPedal=1;float time=-1,t40=-1;for(int i=0;i<1200;i++){car.Tick(.02f);Physics.Simulate(.02f);if(t40<0&&car.SpeedKph>=40)t40=(i+1)*.02f;if(car.SpeedKph>=100){time=(i+1)*.02f;break;}}LastRollOn=time-t40;UnityEngine.Object.DestroyImmediate(model);return time;}
 public static void Run(){
  root=Path.GetFullPath("Verification/Boost/Fixtures_"+Id());Directory.CreateDirectory(root);report.Clear();oldMode=Physics.simulationMode;
  try{
   var c=JsonUtility.FromJson<GarageCatalog>(Resources.Load<TextAsset>("FinchGarageCatalog").text);c.Validate();var trial=JsonUtility.FromJson<TrialDefinition>(Resources.Load<TextAsset>("FirstDocksideTrial").text);
   Check(c.gearboxOffer.price==250&&c.turboOffer.price==1900&&c.intercoolerOffer.price==400,"Imported one-location prices: gearbox 250, turbo kit 1900, street intercooler 400");
   FinchPowertrain engine=new FinchPowertrain(c.turboBasic),other=new FinchPowertrain(c.turboBasic);float off=engine.ResolveTorque(4500,1,true,false,.001f);Check(off>=125&&off<126,"Fresh turbo starts on off-boost curve");float steady=0;for(int i=0;i<300;i++)steady=engine.ResolveTorque(4500,1,true,false,.02f);Check(Mathf.Abs(steady-158)<.1f&&engine.TurboAvailability>.99f,"Loaded spool approaches 158 Nm net steady curve without double boost");Check(other.TurboAvailability==0,"Spool state is per vehicle");float prior=engine.TurboAvailability;engine.ResolveTorque(4500,0,true,false,.25f);Check(engine.TurboAvailability<prior*.4f,"Throttle lift decays boost with authored fall constant");for(int i=0;i<100;i++)engine.ResolveTorque(4500,1,true,false,.02f);float cut=engine.ResolveTorque(4500,1,true,true,.25f);Check(cut==0&&engine.TurboAvailability<.4f,"Shift cut removes torque and decays spool");engine.Reset();for(int i=0;i<100;i++)engine.ResolveTorque(4500,1,false,false,.02f);Check(engine.TurboAvailability==0,"Unloaded/free-air demand cannot build boost");Check(engine.ResolveTorque(2000,1,true,false,.02f)==c.turboBasic.SampleOffBoost(2000),"Below-threshold output remains off boost");
   var cool=new FinchPowertrain(c.turboStreet);float coolTorque=cool.ResolveTorque(4500,1,true,false,10);Check(Mathf.Abs(coolTorque-162)<.01f&&c.turboStreet.PeakKw()>c.turboBasic.PeakKw()&&c.turboStreet.PeakKw()<=90,"Street cooler selects matched 162 Nm curve; peak stays under 90 kW");Check(c.turboBasic.SampleOffBoost(4500)==c.turboStreet.SampleOffBoost(4500),"Cooler does not invent off-boost or another boost multiplier");
   var store=new RaceProgressStore(Path.Combine(root,"seed.json"),trial);for(int i=0;i<4;i++)store.Settle(Finish(trial),out _);Check(store.Profile.availableCredits==3200,"Four valid gold fixtures fund 3200 credits");Check(Denied(()=>store.PurchasePart(Id(),c.turboOffer,1900,out _)),"Turbo cannot skip Stage 1/gearbox");Check(Denied(()=>store.PurchasePart(Id(),c.intercoolerOffer,400,out _)),"Intercooler cannot precede turbo kit");Check(Denied(()=>store.PurchasePart(Id(),c.gearboxOffer,250,out _)),"Supporting gearbox cannot skip paid Stage 1");store.PurchaseStageOne(Id(),c.offer,400,out _);
   // Serialize actual compatible schema-2 fields to verify paid Stage-1 migration.
   var old=JsonUtility.FromJson<RaceProgress>(JsonUtility.ToJson(store.Profile));old.version=2;string legacy=Path.Combine(root,"legacy-v2.json");string oldText=JsonUtility.ToJson(old,true);File.WriteAllText(legacy,oldText);string file=Path.Combine(root,"parts-v3.json");var v3=new RaceProgressStore(file,trial,legacyFile:legacy);Check(v3.Profile.version==4&&v3.Profile.engineStage==1&&v3.Profile.availableCredits==2800,"V2 paid tune/earnings migrate into v3 without charging Stage 1 again");Check(Denied(()=>v3.PurchasePart(Id(),c.turboOffer,1900,out _)),"Turbo still requires supporting gearbox after migration");v3.PurchasePart(Id(),c.gearboxOffer,250,out _);Check(Mathf.Abs(c.DefinitionFor(v3.Profile).shiftSeconds-.396f)<.0001f,"Paid gearbox shortens actual shift interruption");string turboId=Id();v3.PurchasePart(turboId,c.turboOffer,1900,out _);Check(v3.Profile.engineStage==2&&v3.Profile.gearboxStage==1&&v3.Profile.intercoolerStage==0&&v3.Profile.availableCredits==650,"Turbo purchase saves Stage 2/basic intercooler and its full sequential fee");v3.PurchasePart(turboId,c.turboOffer,1900,out var duplicate);Check(duplicate&&v3.Profile.availableCredits==650,"Duplicate turbo request pays once");Check(Denied(()=>v3.PurchasePart(Id(),c.turboOffer,1900,out _)),"New request cannot rebuy turbo Stage 2");
   var fault=new RaceProgressStore(file,trial,()=>{throw new IOException("Injected part-save failure");});bool failed=false;try{fault.PurchasePart(Id(),c.intercoolerOffer,400,out _);}catch(IOException){failed=true;}Check(failed&&new RaceProgressStore(file,trial).Profile.intercoolerStage==0&&fault.Profile.availableCredits==650,"Failed cooler write cannot debit or install");v3.PurchasePart(Id(),c.intercoolerOffer,400,out _);var reload=new RaceProgressStore(file,trial,legacyFile:legacy);Check(reload.Profile.engineStage==2&&reload.Profile.gearboxStage==1&&reload.Profile.intercoolerStage==1&&reload.Profile.availableCredits==250&&reload.Profile.spending.Count==4,"V3 reload preserves all four paid receipts and 250 remaining credits");Check(File.ReadAllText(legacy)==oldText,"V2 file remains unchanged");Check(c.DefinitionFor(reload.Profile).SampleTorque(4500)==162&&Mathf.Abs(c.DefinitionFor(reload.Profile).shiftSeconds-.396f)<.0001f,"Reload resolves cooler curve and supporting shift timing");Check(c.stock.shiftSeconds==.45f&&c.turboStreet.shiftSeconds==.45f,"Repeated build application never compounds source shift modifiers");
   EditorSceneManager.OpenScene("Assets/HarborValeGreybox/Driving/Scenes/Finch_HandlingTest.unity");foreach(var spec in UnityEngine.Object.FindObjectsByType<StarterCarSpecification>(FindObjectsSortMode.None))UnityEngine.Object.DestroyImmediate(spec.gameObject);Physics.simulationMode=SimulationMode.Script;
   float na=Acceleration(c.stageOne),naRoll=LastRollOn;var basic=JsonUtility.FromJson<FinchDefinition>(JsonUtility.ToJson(c.turboBasic));basic.shiftSeconds*=c.gearboxShiftMultiplier;float turbo=Acceleration(basic),turboRoll=LastRollOn,street=Acceleration(c.DefinitionFor(reload.Profile)),streetRoll=LastRollOn;Check(naRoll>0&&turboRoll<naRoll&&streetRoll<turboRoll,"Measured rolling 40-100: Stage1 "+naRoll.ToString("F2")+" s, turbo "+turboRoll.ToString("F2")+" s, street cooler "+streetRoll.ToString("F2")+" s");Check(na>0&&turbo>0&&street>0&&turbo<na-.5f&&street<turbo-.03f,"Measured 0-100: Stage1 NA "+na.ToString("F2")+" s, turbo/basic cooler "+turbo.ToString("F2")+" s, turbo/street cooler "+street.ToString("F2")+" s");
   File.WriteAllLines("Verification/Boost/rule-physics-results.txt",report);Debug.Log("FINCH_BOOST_RULE_PHYSICS_PASS");
  }catch(Exception e){report.Add(e.ToString());File.WriteAllLines("Verification/Boost/rule-physics-results.txt",report);throw;}finally{Physics.simulationMode=oldMode;}
 }
}
}

